<template>
  <div class="sv-main">
    <div class="title-wrap">
      <div class="title-box">
        <img class="title-logo" src="@/assets/image/wmlLogo.png" alt />
        <span class="title-font">智能营销</span>
        <span class="title-desc">版本日志</span>
      </div>
    </div>
    <div class="sv-wrap" v-loading="loading">
      <div class="sv-box">
        <div class="sv-option" v-for="(item, index) of logData" :key="index">
          <div class="version-title-box">
            <div class="version-title-left">
              <div class="system-name">{{ item.Title }}</div>
              <div class="version-num">{{ item.Version }}</div>
            </div>
            <div class="version-title-right">
              <div class="update-time">{{ item.UpdateTime }}</div>
              <div class="update-action">更新</div>
            </div>
          </div>
          <div class="version-content">
            <div class="version-content-title">功能特性</div>
            <div
              class="version-content-option"
              v-for="infoItem of item.UpdateInfoList"
              :key="infoItem"
            >
              <div class="version-option-icon"></div>
              <div class="version-option-content">{{ infoItem }}</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  name: 'setting_version',
  data () {
    return {
      logData: [],
      loading: false
    }
  },
  methods: {
    init () {
      this.loading = true
      this.SharpObj.getUpdateRecord(res => {
        res = JSON.parse(res)
        this.loading = false
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.logData = res.Data
      })
    }
  },
  created () {
    this.init()
  }
}
</script>
<style lang="scss" scoped>
.sv-main {
  width: 100%;
  height: 100%;
  background-color: #fff;
  display: flex;
  flex-direction: column;
}

.title-wrap {
  flex-shrink: 0;
  width: 100%;
  background-color: #f6fcffb3;
  padding: 23px 0;
  margin: 20px 0 38px 0;
  .title-box {
    width: 800px;
    margin: 0 auto;
    display: flex;
    align-items: flex-end;
    .title-logo {
      width: 38px;
      height: 38px;
    }
    .title-font {
      font-size: 30px;
      margin: 0 8px;
      color: #0daeff;
    }
    .title-desc {
      color: #0daeff;
      font-weight: 700;
      font-size: 16px;
    }
  }
}

.sv-wrap {
  width: 100%;
  flex-grow: 1;
  overflow: auto;
  .sv-box {
    width: 800px;
    margin: 0 auto;
    padding-bottom: 38px;
    .sv-option {
      width: 100%;
      padding-bottom: 70px;
      .version-title-box {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 10px 0;
        border-bottom: 1px solid #e8e8f1;
        .version-title-left {
          display: flex;
          align-items: center;
          .system-name {
            font-size: 18px;
            color: #00a1ef;
          }
          .version-num {
            font-size: 18px;
            color: #00a1ef;
            margin-left: 10px;
          }
        }
        .version-title-right {
          display: flex;
          .update-action {
            margin-left: 10px;
          }
        }
      }

      .version-content {
        padding-top: 10px;
        .version-content-title {
          width: 100%;
          color: #333333;
          padding: 10px 0;
        }
        .version-content-option {
          width: 100%;
          display: flex;
          align-items: center;
          padding: 10px 0;
          .version-option-icon {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background-color: #0daeff;
            flex-shrink: 0;
            margin: 0 10px 0 20px;
          }
          .version-option-content {
            flex-grow: 1;
            color: #333333;
          }
        }
      }
    }
  }
}
</style>
